 gsc:{name:'Search Console',fields:['date','branch','query','page','device','impressions','clicks','position'],numeric:['impressions','clicks','position'],sample:['2026-11-20','nilufer','nilüfer oto ekspertiz','https://ototr.com/nilufer','mobile',120,6,8.2],note:'Son 180 gün; sorgu, sayfa, cihaz ve tarih. Farklı boyut kırılımlarının toplamlarını aynı ölçüm gibi birleştirmeyin.'},
