 ga4:{name:'Google Analytics 4',fields:['date','branch','landing_page','sessions','engaged_sessions','key_event_sessions'],numeric:['sessions','engaged_sessions','key_event_sessions'],sample:['2026-11-20','nilufer','/nilufer',50,35,4],note:'Oturum ve açılış sayfası raporları; kaynak/aracı ayrımı. Önemli etkinlik gerçekleşen oturum sayısı, ham etkinlik sayısından ayrı alınmalı.'},
